<?php
namespace App\Http\Controllers;use App\Models\Book;use App\Models\BookCollaborationInvite;use App\Models\User;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class TeamController extends Controller{private const PERMISSIONS=['full','correct','translate','audio','design','publish'];public function index(Request $r):JsonResponse{$u=$this->user($r);$sent=BookCollaborationInvite::query()->where('owner_id',$u->id)->with('book:id,name,key_book')->latest()->get();$received=BookCollaborationInvite::query()->where('email',strtolower($u->email))->where('status','pending')->with(['book:id,name,key_book','owner:id,name,email'])->latest()->get();return response()->json(['data'=>['books'=>Book::query()->where('account_id',$u->id)->get(['key_book','name']),'sent'=>$sent->map(fn($i)=>$this->out($i)),'received'=>$received->map(fn($i)=>$this->out($i,true))]]);}public function invite(Request $r):JsonResponse{$u=$this->user($r);$d=$r->validate(['key_book'=>['required','string'],'email'=>['required','email'],'permissions'=>['required','array','min:1'],'permissions.*'=>['in:full,correct,translate,audio,design,publish']]);$book=Book::query()->where('account_id',$u->id)->where('key_book',$d['key_book'])->firstOrFail();$email=strtolower($d['email']);abort_if($email===strtolower($u->email),422,'You already own this book.');$invite=BookCollaborationInvite::query()->updateOrCreate(['book_id'=>$book->id,'email'=>$email],['owner_id'=>$u->id,'invited_user_id'=>User::query()->where('email',$email)->value('id'),'permissions'=>in_array('full',$d['permissions'],true)?['full']:array_values($d['permissions']),'status'=>'pending','accepted_at'=>null,'declined_at'=>null]);return response()->json(['data'=>['invite'=>$this->out($invite->load('book:id,name,key_book'))]],201);}public function respond(Request $r,BookCollaborationInvite $invite):JsonResponse{$u=$this->user($r);abort_unless(strtolower($invite->email)===strtolower($u->email),403);$d=$r->validate(['accept'=>['required','boolean']]);$invite->update(['invited_user_id'=>$u->id,'status'=>$d['accept']?'accepted':'declined','accepted_at'=>$d['accept']?now():null,'declined_at'=>$d['accept']?null:now()]);return response()->json(['data'=>['invite'=>$this->out($invite->fresh()->load('book:id,name,key_book'),true)]]);}public function destroy(Request $r,BookCollaborationInvite $invite):JsonResponse{$u=$this->user($r);abort_unless($invite->owner_id===$u->id,403);$invite->delete();return response()->json([],204);}private function user(Request $r):User{$u=$r->user();abort_unless($u,401);return $u;}private function out(BookCollaborationInvite $i,bool $owner=false):array{return ['id'=>$i->id,'email'=>$i->email,'book_name'=>$i->book?->name,'book_key'=>$i->book?->key_book,'permissions'=>$i->permissions,'status'=>$i->status,'owner_name'=>$owner?$i->owner?->name:null,'created_at'=>$i->created_at?->toISOString()];}}
